import manifest from "./self-hosted-fonts.json";

type Face = { weight: number; subset: string; file: string; unicodeRange: string };
const selfHosted: Record<string, { faces: Face[] }> = manifest;

// Family names go into a URL and a CSS string; anything else is dropped.
const SAFE_FAMILY = /^[A-Za-z0-9 ]{1,64}$/;
export const MAX_FAMILIES = 10;

/**
 * Stylesheet for the requested families. Self-hosted families (generated by
 * scripts/sync-fonts.ts) become @font-face rules pointing at /fonts; any other
 * family is @imported from Google Fonts so the full picker catalog still works.
 */
export function buildFontCss(families: string[]): string {
  const requested = [...new Set(families.filter((f) => SAFE_FAMILY.test(f)))].slice(0, MAX_FAMILIES);
  const remote = requested.filter((f) => !selfHosted[f]);
  const local = requested.filter((f) => selfHosted[f]);

  // @import must precede every other rule.
  const imports = remote.length
    ? [
        `@import url("https://fonts.googleapis.com/css2?${remote
          .map((f) => `family=${encodeURIComponent(f)}:wght@300;400;700`)
          .join("&")}&display=swap");`,
      ]
    : [];

  const faces = local.flatMap((family) =>
    selfHosted[family].faces.map(
      (face) =>
        `@font-face{font-family:'${family}';font-style:normal;font-weight:${face.weight};font-display:swap;` +
        `src:url(${face.file}) format('woff2');unicode-range:${face.unicodeRange};}`
    )
  );

  return [...imports, ...faces].join("\n");
}
